# Surplus production model of the tuna data ----
## Setup ----
tuna_frame <- FIMSFrame(data_limited_tuna)
stan_median <- function(label) {
  data_limited_tuna_results[["median"]][
    data_limited_tuna_results[["label"]] == label
  ]
}
# Depletion of the tuna Schaefer model with no process error, r = 0.2938193196
# and K = 266229.6192 mt, from
# StateSpaceSIR::GENERALIZED_LOGISTIC(allee_model = 0, r_max = r, K = K,
# N1 = K, z = 1, P50 = 0, start_yr = 1967, num_Yrs = 24, catches = catch,
# proc_error = rep(1, 23), MVP = 0) divided by K. The last value is the start
# of 1990, the year after the last year.
state_space_sir_depletion <- c(
  1.0000000000, 0.9402771185, 0.8602436425, 0.7885174806, 0.7484932050,
  0.7099011213, 0.6453307213, 0.6066561867, 0.6027723880, 0.6073911189,
  0.6049635618, 0.5940483106, 0.5781370785, 0.5652845115, 0.5529735520,
  0.5369585837, 0.5007079334, 0.5200739686, 0.5438291397, 0.5100447123,
  0.4535068969, 0.3854707518, 0.3577871266, 0.3302688587
)

## IO correctness ----
test_that("surplus production model matches StateSpaceSIR with no process error", {
  # The process values are the StateSpaceSIR log depletion, so the process
  # residuals are 0 if the depletion equations match.
  parameters <- setup_default_parameters(
    tuna_frame,
    model_type = "SurplusProduction"
  ) |>
    dplyr::rows_update(
      tibble::tibble(
        label = c("log_growth_rate", "log_carrying_capacity"),
        value = log(c(0.2938193196, 266229.6192))
      ),
      by = "label"
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_depletion",
        timing = 1968:1989,
        value = log(state_space_sir_depletion[2:23])
      ),
      by = c("label", "timing")
    )
  report <- parameters |>
    initialize_fims(data = tuna_frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()
  # The smooth floor on expected depletion adds about 2.5e-6 / P, a relative
  # difference of 2.5e-6 / P^2, which is under 1e-4 for P above 0.16.
  #' @description Test that the expected depletion in 1968 to 1989 equals the StateSpaceSIR depletion.
  expect_equal(
    object = exp(report[["log_expected_depletion"]]),
    expected = state_space_sir_depletion[2:23],
    tolerance = 1e-4
  )
  #' @description Test that depletion, including the start of 1990, equals the StateSpaceSIR depletion.
  expect_equal(
    object = report[["depletion"]][[1]],
    expected = state_space_sir_depletion,
    tolerance = 1e-4
  )
})

test_that("surplus production fit to the tuna data is close to the Stan posterior medians", {
  # The Meyer and Millar (1999) priors on r and K are lognormal, so they are
  # normal priors on log r and log K. Their K is in thousands of metric tons,
  # so log(1000) is added to the mean of the prior on log K. The process and
  # index sds are held at the Stan posterior medians, because FIMS has no
  # inverse gamma prior for their variances.
  parameters <- setup_default_parameters(
    tuna_frame,
    model_type = "SurplusProduction"
  ) |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_sd",
        value = log(sqrt(stan_median("sigma2_depletion")))
      ),
      by = "label"
    ) |>
    dplyr::bind_rows(tibble::tibble(
      module_name = "Data",
      fleet = "survey1",
      label = "index_log_sd",
      value = log(sqrt(stan_median("sigma2_obs"))),
      estimation_type = "constant"
    )) |>
    add_priors(
      log_growth_rate ~ normal(mean = -1.38, sd = 1 / sqrt(3.845)),
      module_name = "Depletion"
    ) |>
    add_priors(
      log_carrying_capacity ~ normal(
        mean = 5.042905 + log(1000), sd = 1 / sqrt(3.7603664)
      ),
      module_name = "Depletion"
    )
  fit <- parameters |>
    initialize_fims(data = tuna_frame) |>
    fit_fims()
  estimates <- get_estimates(fit)
  estimate_of <- function(label) {
    estimates[["estimated"]][estimates[["label"]] == label]
  }
  standard_error_of <- function(label) {
    estimates[["uncertainty"]][estimates[["label"]] == label]
  }

  #' @description Test that the tuna fit converges.
  expect_equal(get_opt(fit)[["convergence"]], 0)
  # The estimates are the posterior mode of log r and log K, with depletion
  # integrated out by the Laplace approximation, not posterior medians. The
  # posterior is skewed, so they differ.
  #' @description Test that log r is within half a standard error of the log of the Stan median.
  expect_lt(
    abs(estimate_of("log_growth_rate") - log(stan_median("growth_rate"))),
    0.5 * standard_error_of("log_growth_rate")
  )
  #' @description Test that log K is within half a standard error of the log of the Stan median.
  expect_lt(
    abs(
      estimate_of("log_carrying_capacity") -
        log(stan_median("carrying_capacity"))
    ),
    0.5 * standard_error_of("log_carrying_capacity")
  )
  #' @description Test that catchability is within half a standard error of the Stan median of q.
  expect_lt(
    abs(estimate_of("catchability") - stan_median("q")),
    0.5 * standard_error_of("catchability")
  )
  # Depletion in the first year is 1 in FIMS, with no process error. In the
  # Stan model it has process error, with a median of 1.017.
  #' @description Test that depletion in the first year is 1, the initial depletion.
  expect_equal(estimate_of("depletion")[1], 1)
  #' @description Test that depletion after the first year is within half a standard error of the Stan medians.
  expect_true(all(
    abs(estimate_of("depletion")[-1] - stan_median("depletion")[-1]) <
      0.5 * standard_error_of("depletion")[-1]
  ))
})

